-- Migration 030 (run after 029). -- METRC tags available (1PN 2026-10-22), loaded as tag ranges per license. Safe to re-run.
-- Each run of consecutive available tags is one range; plant vs package from the 7th character of the tag.
--   CCL24-0000156 plant: 14,612 tags in 50 ranges
--   CCL24-0000156 package: 682 tags in 44 ranges
set client_min_messages = warning;

delete from tag_ranges where license in ('CCL24-0000156') and notes like 'METRC export%';

select license, purpose, count(*) as ranges, sum(last_n - first_n + 1) as tags from tag_ranges
 where license in ('CCL24-0000156') group by 1, 2 order by 1, 2;
